import java.util.*;class TaskBinding{static Object patient(long id,long card,String diagnosis){return new Patient(id,"Учебный","Иван","Иванович","Учебный адрес","00123",card,diagnosis);}static Object shortValue(long id,String surname){return new Patient(id,surname);}static Object[]array(Object...a){return Arrays.copyOf(a,a.length,Patient[].class);}static Object[]diagnosis(Object[]a,String s){return Patient.diagnosis((Patient[])a,s);}static Object[]range(Object[]a,long lo,long hi){return Patient.range((Patient[])a,lo,hi);}static List<?>value(Object x){Patient p=(Patient)x;return List.of(p.id(),p.last(),p.first(),p.middle(),p.address(),p.phone(),p.card(),p.diagnosis());}static void edit(Object x,long id,String last,String first,String middle,String address,String phone,long card,String diagnosis){Patient p=(Patient)x;p.id(id);p.last(last);p.first(first);p.middle(middle);p.address(address);p.phone(phone);p.card(card);p.diagnosis(diagnosis);}static String text(Object x){return x.toString();}}
